import{_ as o,c as a,o as t,a5 as i}from"./chunks/framework.DuCYAsAJ.js";const m=JSON.parse('{"title":"Twitter 系统设计 Walkthrough","description":"","frontmatter":{"title":"Twitter 系统设计 Walkthrough","date":"2026-04-26T00:00:00.000Z","order":8},"headers":[],"relativePath":"posts/SystemDesign/twitter.md","filePath":"posts/SystemDesign/twitter.md","lastUpdated":1779463578000}'),r={name:"posts/SystemDesign/twitter.md"};function l(d,e,c,n,h,s){return t(),a("div",null,[...e[0]||(e[0]=[i('<h2 id="twitter-系统设计-walkthrough" tabindex="-1">Twitter 系统设计 Walkthrough <a class="header-anchor" href="#twitter-系统设计-walkthrough" aria-label="Permalink to &quot;Twitter 系统设计 Walkthrough&quot;">​</a></h2><p>本文设计的是一个类似 Twitter 的社交产品。用户可以发推、关注别人，并在首页看到自己和关注者发布的最新内容。它和 <code>FB News Feed</code> 的功能表面类似，但这里会把问题空间主动收缩到几条可落地的核心链路：发推、关注、首页时间线和分页。围绕这条主线，设计会先给出一个能工作的基础版本，再逐步演进到时间线生成、celebrity 用户和缓存。</p><h3 id="问题定义与边界" tabindex="-1">问题定义与边界 <a class="header-anchor" href="#问题定义与边界" aria-label="Permalink to &quot;问题定义与边界&quot;">​</a></h3><h4 id="功能需求" tabindex="-1">功能需求 <a class="header-anchor" href="#功能需求" aria-label="Permalink to &quot;功能需求&quot;">​</a></h4><p>用户能够发推；用户能够关注和取关其他用户；用户能够看到一条按时间倒序排列的首页时间线；用户能够分页浏览更早的推文。</p><h4 id="非功能需求" tabindex="-1">非功能需求 <a class="header-anchor" href="#非功能需求" aria-label="Permalink to &quot;非功能需求&quot;">​</a></h4><ol><li>高可用：优先可用性，允许最终一致</li><li>低延迟：首页加载希望在 <code>200ms ~ 500ms</code> 内完成</li><li>大规模：需要支撑亿级到十亿级用户</li><li>高扩展：普通用户和 celebrity 用户的访问模式差异极大</li></ol><h4 id="本文暂不展开" tabindex="-1">本文暂不展开 <a class="header-anchor" href="#本文暂不展开" aria-label="Permalink to &quot;本文暂不展开&quot;">​</a></h4><p>点赞、评论、转发、引用推，搜索、推荐、广告混排，话题趋势、审核、反垃圾，以及复杂隐私控制和圈子。Twitter 的完整产品面很大，如果不先主动收缩范围，后面的设计就很容易发散。</p><h3 id="核心实体、接口与数据模型" tabindex="-1">核心实体、接口与数据模型 <a class="header-anchor" href="#核心实体、接口与数据模型" aria-label="Permalink to &quot;核心实体、接口与数据模型&quot;">​</a></h3><h4 id="核心实体" tabindex="-1">核心实体 <a class="header-anchor" href="#核心实体" aria-label="Permalink to &quot;核心实体&quot;">​</a></h4><p><code>User</code>、<code>Tweet</code>、<code>Follow</code>、<code>HomeTimeline</code>、<code>UserTimeline</code>。这里最重要的拆分是把“作者自己的发帖流”和“用户首页看到的聚合流”分开：<code>UserTimeline</code> 是某个用户自己发过的推文，<code>HomeTimeline</code> 是某个用户首页看到的混合时间线。这是整个 Twitter 设计的核心抽象，只要这个拆分立住，后面的 fan-out 讨论都会顺很多。</p><h4 id="初始-api" tabindex="-1">初始 API <a class="header-anchor" href="#初始-api" aria-label="Permalink to &quot;初始 API&quot;">​</a></h4><ul><li>发推：<code>POST /tweets</code></li><li>关注：<code>PUT /users/{id}/follow</code></li><li>取关：<code>DELETE /users/{id}/follow</code></li><li>获取首页：<code>GET /timeline/home?cursor={cursor}&amp;limit={limit}</code></li><li>获取个人页：<code>GET /timeline/user/{userId}?cursor={cursor}&amp;limit={limit}</code></li></ul><p>这里的 <code>cursor</code> 更适合使用某条推文的时间戳或 tweet ID，而不是页码。时间线数据会持续新增，页码很容易被新插入的数据打乱。</p><h4 id="基础数据模型" tabindex="-1">基础数据模型 <a class="header-anchor" href="#基础数据模型" aria-label="Permalink to &quot;基础数据模型&quot;">​</a></h4><p><code>Tweet</code> 主键 <code>tweetId</code>，字段 <code>authorId</code>、<code>content</code>、<code>createdAt</code>，索引 <code>authorId + createdAt</code>。<code>Follow</code> 主键 <code>followerId + followeeId</code>，反向索引 <code>followeeId + followerId</code>。<code>HomeTimeline</code> 主键 <code>userId</code>，值为按时间倒序排列的一组轻量 tweet 引用。这里的关键点和前面的 feed 题一样：timeline 里尽量放轻量引用，例如 <code>tweetId</code>，正文、作者、媒体等详情在读取时再批量补齐。</p><h3 id="核心架构设计" tabindex="-1">核心架构设计 <a class="header-anchor" href="#核心架构设计" aria-label="Permalink to &quot;核心架构设计&quot;">​</a></h3><h4 id="一、用户能够发推" tabindex="-1">一、用户能够发推 <a class="header-anchor" href="#一、用户能够发推" aria-label="Permalink to &quot;一、用户能够发推&quot;">​</a></h4><p>基础设计可以保持直接：客户端请求 <code>POST /tweets</code>，<code>Tweet Service</code> 写入 <code>Tweet Store</code>，该推文进入作者自己的 <code>UserTimeline</code>。如果只要求“用户能发推并在个人主页看到自己的推文”，到这里已经够了。在工程上，<code>Tweet Store</code> 通常会选择一个高写入、按 key 访问友好的存储系统。重点不是具体产品名，而是 tweet 是 append-heavy 的，按 <code>tweetId</code> 和 <code>authorId + time</code> 两种方式读取很常见，需要容易分片和水平扩展。</p><h4 id="二、用户能够关注别人" tabindex="-1">二、用户能够关注别人 <a class="header-anchor" href="#二、用户能够关注别人" aria-label="Permalink to &quot;二、用户能够关注别人&quot;">​</a></h4><p>关注关系本质上是一条单向边：<code>A -&gt; B</code> 表示 A 关注了 B。这个结构看起来简单，但它会直接决定发布时要 fan-out 给谁、读取时需要从谁那里聚合内容。所以关系存储至少要支持两类访问：按 <code>followerId</code> 查关注列表，按 <code>followeeId</code> 查粉丝列表。如果只支持一侧，另一侧链路就会非常痛苦。</p><h4 id="三、用户能够看到首页时间线" tabindex="-1">三、用户能够看到首页时间线 <a class="header-anchor" href="#三、用户能够看到首页时间线" aria-label="Permalink to &quot;三、用户能够看到首页时间线&quot;">​</a></h4><p>基础做法是读时聚合：查当前用户关注了哪些人，逐个拉这些人的最近推文，在应用层合并排序，返回最新的一页。这套方案完全能工作，适合作为基础版本。但它的问题也非常明显：用户可能关注很多人，每个被关注者都可能发过很多推文，每次打开首页都要做大量下游查询和排序，这就是典型的 <code>fan-out on read</code>。</p><h4 id="四、用户能够分页浏览更早内容" tabindex="-1">四、用户能够分页浏览更早内容 <a class="header-anchor" href="#四、用户能够分页浏览更早内容" aria-label="Permalink to &quot;四、用户能够分页浏览更早内容&quot;">​</a></h4><p>分页本身可以通过游标完成：第一次请求不带 cursor，返回最新 <code>N</code> 条；后续请求带上当前页最老那条 tweet 的时间戳或 ID；服务只返回更旧的数据。这在 <code>UserTimeline</code> 和 <code>HomeTimeline</code> 上都适用。相比页码分页，游标分页更稳定，也更符合时间线这种持续追加的数据结构。</p><h3 id="深入讨论" tabindex="-1">深入讨论 <a class="header-anchor" href="#深入讨论" aria-label="Permalink to &quot;深入讨论&quot;">​</a></h3><h4 id="一、为什么不能一直靠读时聚合" tabindex="-1">一、为什么不能一直靠读时聚合 <a class="header-anchor" href="#一、为什么不能一直靠读时聚合" aria-label="Permalink to &quot;一、为什么不能一直靠读时聚合&quot;">​</a></h4><p>如果一个用户关注了 <code>1000</code> 个人，而每个人最近都有几条推文，那么一次首页请求就会扇出大量查询，还要做 merge sort。对小系统来说，这可以接受；对大系统来说，这会变成首页延迟和数据库压力的直接来源。所以更好的思路是把首页时间线提前算出来，也就是引入 <code>HomeTimeline</code>：某个作者发新 tweet 时，系统把这条 tweet 的引用提前写进粉丝的 <code>HomeTimeline</code>。这样首页读取时，就不再需要去很多作者那里拉数据，而是直接按 <code>userId</code> 读自己的 HomeTimeline。这本质上是把一部分计算从读路径前移到写路径，也就是从 <code>fan-out on read</code> 转成 <code>fan-out on write</code>。</p><h4 id="二、为什么又不能对所有人都做写扩散" tabindex="-1">二、为什么又不能对所有人都做写扩散 <a class="header-anchor" href="#二、为什么又不能对所有人都做写扩散" aria-label="Permalink to &quot;二、为什么又不能对所有人都做写扩散&quot;">​</a></h4><p>写扩散能显著降低首页读取成本，但 celebrity 用户会立刻放大它的代价。如果一个普通用户只有几百个粉丝，那么发一条 tweet 时写几百次 <code>HomeTimeline</code> 完全可以接受；但如果一个 celebrity 有几千万粉丝，一次发推就会触发灾难级写放大。因此，全推模式并不现实。更合理的方案是混合模型：普通用户走 fan-out on write，celebrity 用户走 fan-out on read。也就是说，对普通用户，tweet 发布后立即写进粉丝首页；对大 V，tweet 只写进自己的 <code>UserTimeline</code>，粉丝打开首页时，再把这些大 V 的最新内容动态 merge 进去。这就是这类时间线系统中经典的 <code>hybrid timeline</code> 方案。</p><h4 id="三、如何把写扩散做成可扩展链路" tabindex="-1">三、如何把写扩散做成可扩展链路 <a class="header-anchor" href="#三、如何把写扩散做成可扩展链路" aria-label="Permalink to &quot;三、如何把写扩散做成可扩展链路&quot;">​</a></h4><p>即使是普通用户，也不应该在发推主请求里同步做所有 fan-out。更合理的流程是：用户发推；<code>Tweet Service</code> 把 tweet 写入 <code>Tweet Store</code>；同时写入作者自己的 <code>UserTimeline</code>；产生一条 tweet-created 事件；事件进入消息队列；<code>Fanout Worker</code> 异步消费事件；Worker 查粉丝列表；将 <code>tweetId</code> 批量写入这些粉丝的 <code>HomeTimeline</code>。这样做好处很明显：发推主链路足够短，fan-out 可以横向扩容，故障时可以重试或回放，系统可以容忍短暂的最终一致延迟。这也是为什么 Twitter 这类系统通常会天然长成“事件驱动架构”。</p><h4 id="四、celebrity-推文怎么动态-merge" tabindex="-1">四、celebrity 推文怎么动态 merge <a class="header-anchor" href="#四、celebrity-推文怎么动态-merge" aria-label="Permalink to &quot;四、celebrity 推文怎么动态 merge&quot;">​</a></h4><p>当系统对大 V 关闭写扩散后，读取首页时就必须补上这一块。一个实用的办法是：先读用户自己的 <code>HomeTimeline</code>，再查这个用户关注的大 V 列表，分别拉这些大 V 最近的少量 tweet，和 HomeTimeline 做一次小规模 merge。这里要注意两个边界：大 V 数量通常远小于总关注数，只需要拉每个大 V 最近很小一段内容。因此这一步虽然也是读时聚合，但它只对少数高粉账号发生，不会退化成最原始的“全量关注聚合”。</p><h4 id="五、缓存应该放在哪一层" tabindex="-1">五、缓存应该放在哪一层 <a class="header-anchor" href="#五、缓存应该放在哪一层" aria-label="Permalink to &quot;五、缓存应该放在哪一层&quot;">​</a></h4><p>Twitter 这类时间线系统非常依赖缓存，但不能一上来就只喊 Redis。至少有三层缓存值得明确说出来。第一层是 Tweet 详情缓存：时间线里通常只放 tweet 引用，所以读取首页后还要批量补正文、作者、媒体等详情，这些 tweet 详情很适合放在缓存里，因为 tweet 发布后大多数时间只读不改，热 tweet 会被大量重复请求，从缓存里批量读可以显著降低主存储压力。第二层是 HomeTimeline 页缓存：对非常活跃的用户，首页会被频繁刷新，可以把首页前几页短时间缓存起来，例如几十秒，代价是新 tweet 进入 Feed 会有轻微延迟并需要处理失效与覆盖问题，但它能换来更稳定的首页延迟。第三层是社交关系缓存：关注列表和粉丝列表在 fan-out 和读时 merge 中都要频繁使用，因此对热点用户，把关系数据缓存在内存里也非常常见，尤其是 celebrity 的粉丝列表，如果每次都直接查底库，会让 fanout worker 本身成为数据库压力放大器。</p><h4 id="六、如何处理热点与不均匀负载" tabindex="-1">六、如何处理热点与不均匀负载 <a class="header-anchor" href="#六、如何处理热点与不均匀负载" aria-label="Permalink to &quot;六、如何处理热点与不均匀负载&quot;">​</a></h4><p>Twitter 最典型的不均匀性来自 celebrity 用户。热点主要会打在三处：粉丝列表读取、tweet 详情读取、首页混合读取。所以系统不仅要分片，更要承认“热点 key 会真实存在”。常见处理方式包括：对 tweet 详情做多副本缓存；对 celebrity 关系数据做专门缓存或预热；将 fan-out worker 和普通时间线 worker 分开；对首页读取做限流、退化和局部缓存。也就是说，困难不在平均负载，而在极端负载。</p><h4 id="七、个人页为什么更简单" tabindex="-1">七、个人页为什么更简单 <a class="header-anchor" href="#七、个人页为什么更简单" aria-label="Permalink to &quot;七、个人页为什么更简单&quot;">​</a></h4><p>和首页时间线相比，个人页 <code>UserTimeline</code> 要简单得多。因为它只需要按 <code>authorId</code> 查某个人自己的推文，按时间倒序分页，这是一条非常规整的单写单读链路，不存在多作者 merge，也没有 fan-out 的问题。首页时间线是复杂路径，个人页时间线是简单路径。把两者分清楚，能更准确地定位系统复杂度的来源。</p><h3 id="整体链路" tabindex="-1">整体链路 <a class="header-anchor" href="#整体链路" aria-label="Permalink to &quot;整体链路&quot;">​</a></h3><h4 id="发推路径" tabindex="-1">发推路径 <a class="header-anchor" href="#发推路径" aria-label="Permalink to &quot;发推路径&quot;">​</a></h4><ol><li>用户请求 <code>POST /tweets</code></li><li><code>Tweet Service</code> 写入 <code>Tweet Store</code></li><li>同时把 tweet 写入作者的 <code>UserTimeline</code></li><li>产生 tweet-created 事件</li><li><code>Fanout Worker</code> 异步消费</li><li>普通用户 fan-out 到粉丝 <code>HomeTimeline</code></li><li>celebrity 用户跳过预计算，只保留在 <code>UserTimeline</code></li></ol><h4 id="关注路径" tabindex="-1">关注路径 <a class="header-anchor" href="#关注路径" aria-label="Permalink to &quot;关注路径&quot;">​</a></h4><ol><li>用户请求 follow / unfollow</li><li><code>Follow Service</code> 更新 <code>Follow Store</code></li><li>同步维护正向和反向查询所需索引</li></ol><h4 id="首页读取路径" tabindex="-1">首页读取路径 <a class="header-anchor" href="#首页读取路径" aria-label="Permalink to &quot;首页读取路径&quot;">​</a></h4><ol><li>读取用户自己的 <code>HomeTimeline</code></li><li>读取其关注的大 V 列表</li><li>拉大 V 最近少量 tweet</li><li>做小规模 merge</li><li>批量补 tweet 详情</li><li>返回最终首页结果</li></ol><h4 id="个人页读取路径" tabindex="-1">个人页读取路径 <a class="header-anchor" href="#个人页读取路径" aria-label="Permalink to &quot;个人页读取路径&quot;">​</a></h4><ol><li>根据 <code>authorId</code> 读取 <code>UserTimeline</code></li><li>按 cursor 分页</li><li>批量补详情</li><li>返回结果</li></ol><h2 id="参考来源" tabindex="-1">参考来源 <a class="header-anchor" href="#参考来源" aria-label="Permalink to &quot;参考来源&quot;">​</a></h2><ul><li><a href="https://www.hellointerview.com/community/questions/twitter-clone-feed/cmgfco6rf05in08adz2rut2nw" target="_blank" rel="noreferrer">Hello Interview 社区题目：Design Twitter</a></li></ul>',52)])])}const w=o(r,[["render",l]]);export{m as __pageData,w as default};
